//! Tests for the committed Round 14 example goldens.
//!
//! The golden margins readings of the standing example
//! meet and of the constructed meet are regenerated by
//! the margins command itself, and these pins fail if an
//! example, a golden, or the reading drifts away from
//! the hand computed margins of either meet, counted by
//! hand from the shipped forks golden's standing events
//! carried forward over the shipped marks golden's marks
//! and cross checked against the shipped standings
//! golden at the three day closes. The day close pin
//! reads the standings reading over the same file and
//! fails when the margins reading's last mark of a day
//! disagrees with the figures that day's standings
//! section computes at its close. Every pin in this
//! file fails before the round by the absence of the
//! reading and its goldens, neither standing on the pre
//! round tree.

use std::fs;
use std::path::PathBuf;

use paceghost::meet::{load_meet_file, meet_margins, meet_standings, Meet};

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

fn golden_lines(name: &str) -> Vec<String> {
    let golden = fs::read_to_string(examples_dir().join(name)).expect("the golden file reads");
    assert!(golden.ends_with('\n'));
    golden.lines().map(str::to_string).collect()
}

fn load_example(file: &str) -> Meet {
    let (meet, defects) = load_meet_file(&examples_dir().join(file));
    assert_eq!(defects, Vec::<String>::new());
    meet.expect("the example meet loads")
}

fn mark_lines(lines: &[String]) -> Vec<&String> {
    lines
        .iter()
        .filter(|line| line.starts_with("mark "))
        .collect()
}

#[test]
fn test_the_example_margins_match_the_golden_bytes() {
    let meet = load_example("meet.json");
    let lines = meet_margins(&meet).expect("the example margins read");
    assert_eq!(lines, golden_lines("meet-margins-golden.txt"));
}

#[test]
fn test_the_constructed_margins_match_the_golden_bytes() {
    let meet = load_example("constructed-meet.json");
    let lines = meet_margins(&meet).expect("the constructed margins read");
    assert_eq!(lines, golden_lines("constructed-meet-margins-golden.txt"));
}

#[test]
fn test_the_example_golden_counts_close_over_its_mark_lines() {
    let golden = golden_lines("meet-margins-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("margins counts, marks walked 16, marks with another standing 15, days 3, closest margin 58.181818 at 1100 seconds on the first day")
    );
    let marks = mark_lines(&golden);
    assert_eq!(marks.len(), 16);
    let with_another = marks
        .iter()
        .filter(|line| line.contains(", nearest standing "))
        .count();
    assert_eq!(with_another, 15);
    let no_other = marks
        .iter()
        .filter(|line| line.ends_with(", and no other standing"))
        .count();
    assert_eq!(no_other, 1);
    assert_eq!(with_another + no_other, marks.len());
}

#[test]
fn test_the_constructed_golden_counts_close_over_its_mark_lines() {
    let golden = golden_lines("constructed-meet-margins-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("margins counts, marks walked 7, marks with another standing 7, days 3, closest margin 50 at 100 seconds on the second day")
    );
    let marks = mark_lines(&golden);
    assert_eq!(marks.len(), 7);
    let with_another = marks
        .iter()
        .filter(|line| line.contains(", nearest standing "))
        .count();
    assert_eq!(with_another, 7);
}

#[test]
fn test_the_example_closest_margin_stands_at_the_sixth_mark() {
    let golden = golden_lines("meet-margins-golden.txt");
    let marks = mark_lines(&golden);
    let sixth = marks[5];
    assert!(
        sixth.starts_with("mark 6, at 1100 seconds on the first day,"),
        "{}",
        sixth
    );
    assert!(sixth.ends_with(", margin 58.181818"), "{}", sixth);
    for earlier in &marks[..5] {
        assert!(!earlier.ends_with(", margin 58.181818"), "{}", earlier);
    }
}

#[test]
fn test_the_example_day_closes_agree_with_the_standings_reading() {
    let meet = load_example("meet.json");
    let margins = meet_margins(&meet).expect("the margins read");
    let standings = meet_standings(&meet).expect("the standings read");
    let mut sections: Vec<Vec<String>> = Vec::new();
    for line in &standings {
        if line.starts_with("day, the ") {
            sections.push(Vec::new());
        }
        if let Some(section) = sections.last_mut() {
            section.push(line.clone());
        }
    }
    let mut margin_sections: Vec<Vec<&String>> = Vec::new();
    for line in &margins {
        if line.starts_with("day, the ") {
            margin_sections.push(Vec::new());
        }
        if let Some(section) = margin_sections.last_mut() {
            section.push(line);
        }
    }
    assert_eq!(sections.len(), 3);
    assert_eq!(margin_sections.len(), 3);
    for (section, margin_section) in sections.iter().zip(margin_sections.iter()) {
        let closing = section
            .iter()
            .find(|line| line.starts_with("close of the "))
            .expect("a standings section closes");
        let holder = closing
            .split("record held by ")
            .nth(1)
            .and_then(|rest| rest.split(" at a projection of ").next())
            .expect("a closing line names its holder");
        let record: f64 = closing
            .rsplit("at a projection of ")
            .next()
            .and_then(|word| word.parse().ok())
            .expect("a closing line names its record figure");
        let mut nearest: Option<(&str, f64)> = None;
        for line in section
            .iter()
            .filter(|line| line.starts_with("competitor "))
        {
            if line.starts_with(&format!("competitor {},", holder)) {
                continue;
            }
            if let Some((label, figure)) = line
                .strip_prefix("competitor ")
                .and_then(|rest| rest.split_once(", standing projection "))
                .and_then(|(label, rest)| {
                    rest.strip_suffix(" at the close")
                        .map(|figure| (label, figure))
                })
            {
                let value: f64 = figure.parse().expect("a standing figure parses");
                if nearest.is_none_or(|(_, best)| value < best) {
                    nearest = Some((label, value));
                }
            }
        }
        let (label, value) = nearest.expect("another competitor stands at the close");
        let last = margin_section
            .iter()
            .rfind(|line| line.starts_with("mark "))
            .expect("the day holds a mark");
        assert!(
            last.contains(&format!(
                ", nearest standing {} held by {}, margin ",
                value, label
            )),
            "{}",
            last
        );
        let margin: f64 = last
            .rsplit(", margin ")
            .next()
            .and_then(|word| word.parse().ok())
            .expect("the last mark names its margin");
        assert!((margin - (value - record)).abs() < 0.000002, "{}", last);
    }
}
